package fuzzy

import "strings"

func Rev(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}
func HasA(s string) bool { return strings.Contains(s, "a") }
EOF
cat > fuzzy/f_test.go <<'EOF'
package fuzzy

import (
	"testing"
	"unicode/utf8"
)

func TestRev(t *testing.T) {
	if Rev("abc") != "cba" {
		t.Fatal("bad")
	}
}

func FuzzRev(f *testing.F) {
	f.Add("abc")
	f.Fuzz(func(t *testing.T, s string) {
		r := Rev(Rev(s))
		if utf8.ValidString(s) && r != s {
			t.Errorf("round trip mismatch: %q vs %q", s, r)
		}
	})
}

func FuzzBad(f *testing.F) {
	f.Add("x")
	f.Fuzz(func(t *testing.T, s string) {
		if len(s) > 3 {
			t.Errorf("too long: %q", s)
		}
	})
}
